<?php defined('BASEPATH') or exit('No direct script access allowed');
class M_qr_siswa extends CI_Model
{
    public function result($f){$this->base($f,true);$total=(int)$this->db->count_all_results();$this->base($f,false);$rows=$this->db->limit($f['limit'],($f['page']-1)*$f['limit'])->get()->result_array();return ['rows'=>$rows,'meta'=>['page'=>$f['page'],'limit'=>$f['limit'],'total'=>$total,'pages'=>max(1,(int)ceil($total/$f['limit']))]];}
    public function print_rows($id_siswa,$kelas){$this->base(['search'=>'','kelas'=>(int)$kelas],false);if((int)$id_siswa>0)$this->db->where('q.id_siswa',(int)$id_siswa);return $this->db->limit((int)$id_siswa>0?1:1000)->get()->result_array();}
    private function base($f,$count){$this->db->select($count?'q.id':'q.id,q.id_siswa,q.nis,q.kode_tampil,q.status_qr,q.versi_qr,q.tanggal_buat,q.waktu_buat,s.nama_lengkap,k.nama_kelas')->from('qr_siswa q')->join('siswa s','s.id=q.id_siswa')->join('kelas_siswa ks',"ks.id=(SELECT MAX(k2.id) FROM kelas_siswa k2 JOIN kelas_setting st2 ON st2.id=k2.id_kelas_setting JOIN master_tahun_ajaran ta2 ON ta2.id=st2.id_periode AND ta2.status='Aktif' WHERE k2.id_siswa=s.id AND k2.status_aktif IN ('1','AKTIF'))",'left',false)->join('kelas_setting k','k.id=ks.id_kelas_setting','left')->where('q.status_qr','AKTIF');if($f['search']!=='')$this->db->group_start()->like('q.nis',$f['search'])->or_like('s.nama_lengkap',$f['search'])->or_like('q.kode_tampil',$f['search'])->group_end();if($f['kelas']>0)$this->db->where('k.id',$f['kelas']);if(!$count)$this->db->order_by('s.nama_lengkap');}
    public function regenerate($id_siswa,$user){$this->db->trans_begin();$wallet=$this->db->query("SELECT id FROM saldo_dompet_siswa WHERE id_siswa=? AND status_dompet='AKTIF' FOR UPDATE",[$id_siswa])->row_array();if(!$wallet){$this->db->trans_rollback();return $this->err('Wallet aktif tidak ditemukan.',404);}$old=$this->db->query("SELECT id,versi_qr FROM qr_siswa WHERE id_siswa=? AND status_qr='AKTIF' FOR UPDATE",[$id_siswa])->result_array();$version=1;foreach($old as $o){$version=max($version,(int)$o['versi_qr']+1);}$this->db->where('id_siswa',$id_siswa)->where('status_qr','AKTIF')->update('qr_siswa',['status_qr'=>'NONAKTIF','tanggal_nonaktif'=>date('Y-m-d'),'waktu_nonaktif'=>date('H:i:s')]);$raw=bin2hex(random_bytes(32));$display=strtoupper(substr(bin2hex(random_bytes(8)),0,12));$student=$this->db->select('nis')->get_where('siswa',['id'=>$id_siswa])->row_array();$this->db->insert('qr_siswa',['id_siswa'=>$id_siswa,'nis'=>$student['nis'],'token_qr_hash'=>hash('sha256',$raw),'kode_tampil'=>$display,'status_qr'=>'AKTIF','versi_qr'=>$version,'tanggal_buat'=>date('Y-m-d'),'waktu_buat'=>date('H:i:s'),'id_user'=>(int)$user['id'],'nama_user'=>$user['nama_user']]);$this->db->insert('log_aktivitas_dompet',['id_user'=>(int)$user['id'],'nama_user'=>$user['nama_user'],'level'=>$user['level'],'modul'=>'QR_SISWA','aksi'=>'REGENERATE','id_referensi'=>$id_siswa,'keterangan'=>'QR lama dinonaktifkan dan QR versi '.$version.' dibuat.','alamat_ip'=>$this->input->ip_address(),'tanggal'=>date('Y-m-d'),'waktu'=>date('H:i:s')]);if($this->db->trans_status()===false){$this->db->trans_rollback();return $this->err('Regenerasi QR gagal.',500);}$this->db->trans_commit();return ['success'=>true,'data'=>['kode_tampil'=>$display,'versi_qr'=>$version]];}
    private function err($m,$s){return ['success'=>false,'message'=>$m,'status'=>$s];}
}
